/* Minimal Bootstrap-compatible interactions for this practice: navbar collapse and carousel. */
document.addEventListener('DOMContentLoaded',function(){
 document.querySelectorAll('[data-bs-toggle="collapse"]').forEach(function(b){b.addEventListener('click',function(){var t=document.querySelector(b.getAttribute('data-bs-target')); if(t)t.classList.toggle('show');});});
 document.querySelectorAll('.carousel').forEach(function(c){var items=[...c.querySelectorAll('.carousel-item')],i=items.findIndex(x=>x.classList.contains('active')); if(i<0)i=0; function show(n){items[i].classList.remove('active');i=(n+items.length)%items.length;items[i].classList.add('active');c.querySelectorAll('.carousel-indicators button').forEach((x,j)=>x.classList.toggle('active',j===i));} c.querySelector('[data-bs-slide="next"]')?.addEventListener('click',()=>show(i+1));c.querySelector('[data-bs-slide="prev"]')?.addEventListener('click',()=>show(i-1));c.querySelectorAll('.carousel-indicators button').forEach((x,j)=>x.addEventListener('click',()=>show(j)));setInterval(()=>show(i+1),5000);});
});
